create or replace function public.admin_list_participant_archives() returns table(archive_id uuid, participant_code text, dni text, email text, archived_at timestamptz, dossier jsonb) language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.profiles where id=auth.uid() and active=true and role in ('admin','superadmin')) then raise exception 'No autorizado'; end if; return query select a.archive_id,a.participant_code,a.dni,a.email,a.archived_at,a.dossier from public.participant_archive a order by a.archived_at desc; end $$; revoke all on function public.admin_list_participant_archives() from public,anon; grant execute on function public.admin_list_participant_archives() to authenticated;